            fly: { enabled: false, altitude: 48, speed: 1, sound: 'Up1', landSound: 'Down1', encounters: false, switchId: 0, noRegion: 0,
                takeOffEvent: 0, landEvent: 0, landMaxHeight: 0 },
            climb: { enabled: false, regions: '', tags: '', speed: -1, switchId: 0 },
