        const fadeOnce = gear > 0 && PIXI.filters && PIXI.filters.AlphaFilter;
        shadow.alpha = fadeOnce ? 1 : alpha;
        if (fadeOnce) {
            shadow._docsFade = shadow._docsFade || new PIXI.filters.AlphaFilter(alpha);
            shadow._docsFade.alpha = alpha;
        }
