//==========================================================
// SECTION 24f: THE EDITOR'S LANGUAGE
//==========================================================
// The editor is written in English. A translation is a file in data/DocsDoodadsLanguages/<code>.json:
// { "language": "Deutsch", "strings": { "Save everything": "Alles speichern", "Placed {n} doodad(s)": "..." } }
// keyed by the English words. Words with {name} in them match any value there and carry it over. When a
// language other than English is picked (More > Look), the editor's panels, cards, tooltips and messages
// are shown in it; anything not translated stays English. npm run strings writes languages/template.json
// with every English string found in the editor's parts, for a translator to fill in.
DocsDoodads.I18n = {
    folder: 'data/DocsDoodadsLanguages',
    lang: 'en',
    name: 'English',
    exact: {},
    patterns: [],
    attributes: ['title', 'placeholder', 'aria-label', 'data-dd-tip'],

    // [{ code, name }]: English and every language file in the folder.
    available() {
        const out = [{ code: 'en', name: 'English' }];
        const FS = DocsDoodads.FS;
        try {
            if (!FS.fs || !FS.existsSync(this.folder)) return out;
            for (const file of FS.fs.readdirSync(this.folder).filter(f => /^[\w-]+\.json$/i.test(f)).sort()) {
                const code = file.replace(/\.json$/i, '');
                if (code === 'en') continue;
                const data = FS.readJson(FS.path.join(this.folder, file));
                out.push({ code, name: (data && data.language) || code });
            }
        } catch (e) {}
        return out;
    },

    // Takes a table ({ language, strings }); English words with {name} become patterns.
    use(code, table) {
        this.lang = code || 'en';
        this.name = (table && table.language) || (this.lang === 'en' ? 'English' : this.lang);
        this.exact = {};
        this.patterns = [];
        const strings = table && table.strings && typeof table.strings === 'object' ? table.strings : {};
        for (const key of Object.keys(strings)) {
            const value = strings[key];
            if (typeof value !== 'string' || !value.trim()) continue;
            if (/\{\w+\}/.test(key)) {
                const names = [];
                const source = key.split(/(\{\w+\})/).map(part => {
                    const m = /^\{(\w+)\}$/.exec(part);
                    if (m) { names.push(m[1]); return '(.+?)'; }
                    return part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                }).join('');
                this.patterns.push({ re: new RegExp('^' + source + '$'), names, value });
            } else {
                this.exact[key] = value;
            }
        }
        return this.lang;
    },

    // Reads data/DocsDoodadsLanguages/<code>.json; 'en' (or a file that can't be read) is English.
    load(code) {
        if (!code || code === 'en') return this.use('en', null);
        const FS = DocsDoodads.FS;
        const table = FS.readJson(FS.path ? FS.path.join(this.folder, code + '.json') : this.folder + '/' + code + '.json');
        return table ? this.use(code, table) : this.use('en', null);
    },

    active() {
        return this.lang !== 'en' && (Object.keys(this.exact).length > 0 || this.patterns.length > 0);
    },

    // The words in the editor's language, with {name} values filled in from vars.
    t(text, vars) {
        let s = String(text === undefined || text === null ? '' : text);
        if (this.active()) {
            const key = s.trim();
            if (this.exact[key] !== undefined) s = s.replace(key, this.exact[key]);
            else {
                for (const p of this.patterns) {
                    const m = p.re.exec(key);
                    if (!m) continue;
                    let out = p.value;
                    p.names.forEach((n, i) => { out = out.split('{' + n + '}').join(m[i + 1]); });
                    s = s.replace(key, out);
                    break;
                }
            }
        }
        if (vars) for (const k of Object.keys(vars)) s = s.split('{' + k + '}').join(String(vars[k]));
        return s;
    },

    // Translates the text and the tooltip-like attributes under a node. Already-translated words don't
    // match English keys, so running it again changes nothing.
    translateTree(root) {
        if (!this.active() || !root) return 0;
        let n = 0;
        const walk = node => {
            if (!node) return;
            if (node.nodeType === 3) {
                const text = node.nodeValue || '';
                if (text.trim()) {
                    const next = this.t(text);
                    if (next !== text) { node.nodeValue = next; n++; }
                }
                return;
            }
            if (node.nodeType === 1) {
                const tag = String(node.tagName || '').toUpperCase();
                if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'CANVAS') return;
                // What someone typed is theirs.
                if ((tag === 'INPUT' || tag === 'TEXTAREA') && node.type !== 'button' && node.type !== 'submit') {
                    this.translateAttributes(node) && n++;
                    return;
                }
                if (this.translateAttributes(node)) n++;
            }
            const kids = node.childNodes || [];
            for (let i = 0; i < kids.length; i++) walk(kids[i]);
        };
        walk(root);
        return n;
    },

    translateAttributes(el) {
        if (!el.getAttribute) return false;
        let changed = false;
        for (const a of this.attributes) {
            const v = el.getAttribute(a);
            if (!v) continue;
            const next = this.t(v);
            if (next !== v) { el.setAttribute(a, next); changed = true; }
        }
        return changed;
    }
};
//==========================================================
// SECTION 24b: DocsDoodads.UiIcons (WORKSPACE PIXEL ICONS)
//==========================================================
// Built from art/ui_icons.png by scripts/icons.js: edit the picture, then run npm run icons.
DocsDoodads.UiIcons = {
    size: 16,
    cols: 8,
    width: 128,
    height: 112,
    names: ["select","stamp","brush","biome","path","terrain","mirror","picker","undo","redo","history","more","save","done","search","bag","star","recent","all","tree","person","tiles","picture","face","sword","scene","window","music","box","map","gear","sparkle","sun","scissors","wrench","trash","layers","eye","lock","folder","grid","sound","help","close","left","right","plus","info","leaf"],
    url: 'data:image/png;base64,'
};

//==========================================================
// SECTION 24c: DocsDoodads.Ui (WORKSPACE LOOK AND FEEL)
//==========================================================
// A bright, friendly look: white rounded panels, chunky "press-down" buttons, big pixel icons, toggle
// switches, and short hints that say what to do next. Colours are CSS variables (--dd-*) so every panel,
// including the ones opened on the page (Screen Looks, Effects Maker, History...), shares them.
DocsDoodads.Ui = {
    prefsKey: 'docsDoodads.ui',

    // Per-computer UI choices (panel folding, sounds, the welcome card). Never needed to work.
    prefs() {
        try {
            const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(this.prefsKey) : null;
            const data = raw ? JSON.parse(raw) : {};
            return data && typeof data === 'object' ? data : {};
        } catch (e) {
            return {};
        }
    },

    setPref(key, value) {
        const data = this.prefs();
        data[key] = value;
        try { if (typeof localStorage !== 'undefined') localStorage.setItem(this.prefsKey, JSON.stringify(data)); } catch (e) {}
        return value;
    },

    // An icon from art/ui_icons.png. scale: 1 (16px), 2 (32px)...
    icon(name, scale = 2, extraClass = '') {
        const I = DocsDoodads.UiIcons;
        const index = I ? I.names.indexOf(name) : -1;
        if (index < 0) return '';
        const x = (index % I.cols) * I.size, y = Math.floor(index / I.cols) * I.size;
        return `<i class="dd-ico ${extraClass}" aria-hidden="true" style="width: ${I.size * scale}px; height: ${I.size * scale}px; ` +
            `background-size: ${I.width * scale}px ${I.height * scale}px; background-position: -${x * scale}px -${y * scale}px;"></i>`;
    },

    // Little sounds from the project's own System sounds (they can be turned off in More).
    sound(kind) {
        if (this.prefs().sounds === false || typeof SoundManager === 'undefined') return;
        try {
            if (kind === 'ok') SoundManager.playOk();
            else if (kind === 'cancel') SoundManager.playCancel();
            else if (kind === 'save') SoundManager.playSave();
            else if (kind === 'buzzer') SoundManager.playBuzzer();
            else SoundManager.playCursor();
        } catch (e) {}
    },

    // What to do next, shown in the bubble at the bottom of the screen.
    hints: {
        none: 'Pick something from the bag, then click the map to place it. Click a placed thing to change it.',
        stamp: 'Stamp: click the map to place the picked item again and again. Esc to stop.',
        brush: 'Scatter: drag over the map to sprinkle the picked item around.',
        biome: 'Paint: drag over the map to paint a mix of plants (set mixes in Map, Biomes).',
        path: 'Path: click to add points, then double-click (or Enter) to lay the item along them.',
        terrain: 'Hills: drag over the map to raise or lower the ground (seen in 3D).',
        eyedropper: 'Pick: click any doodad on the map to pick up what it is made of.'
    },

    setHint(text) {
        const el = typeof document !== 'undefined' ? document.getElementById('dd-status-left') : null;
        if (el) el.textContent = text;
    },

    css: `
:root {
    --dd-panel: #ffffff;
    --dd-panel-2: #f7f5fc;
    --dd-field: #f2f0f8;
    --dd-line: #e3dff0;
    --dd-line-soft: #ece9f5;
    --dd-text: #2f2a43;
    --dd-muted: #6f6a86;
    --dd-faint: #9c97b0;
    --dd-accent: #1f8bff;
    --dd-primary: #2e9bff;
    --dd-primary-dark: #1c74d6;
    --dd-primary-soft: #e3f1ff;
    --dd-good: #2fc26b;
    --dd-good-dark: #1f9450;
    --dd-good-soft: #dff7e8;
    --dd-danger: #ff5a5f;
    --dd-danger-dark: #d63c41;
    --dd-danger-soft: #ffe4e5;
    --dd-warn: #e09b00;
    --dd-warn-soft: #fff4c9;
    --dd-purple: #8a63f0;
    --dd-pink: #f2559c;
    --dd-rim: #ffffff;
    --dd-primary-line: #b8dbff;
    --dd-check-a: #f4f2fa;
    --dd-check-b: #e8e5f1;
    --dd-switch-off: #d9d4e7;
    --dd-switch-line: #cbc5dc;
    --dd-scroll: #d6d1e6;
    --dd-tint: rgba(46, 155, 255, 0.08);
    --dd-shadow: 0 4px 0 rgba(47, 42, 67, 0.10), 0 12px 30px rgba(20, 16, 40, 0.30);
    --dd-font: 'Doodads Nunito', 'Nunito', 'M PLUS Rounded 1c', 'rmmz-mainfont', 'Segoe UI', system-ui, sans-serif;
}
#dd-asset-workspace-root, .dd-glass { font-family: var(--dd-font); }
#dd-asset-workspace-root *, .dd-glass * { box-sizing: border-box; }
.dd-glass {
    background: var(--dd-panel);
    border: 3px solid var(--dd-rim);
    border-radius: 20px;
    color: var(--dd-text);
    box-shadow: var(--dd-shadow);
    pointer-events: auto;
    font-size: 12px;
    font-weight: 600;
}
.dd-glass b, .dd-glass strong { font-weight: 800; }
.dd-ico { display: inline-block; flex: none; background-image: var(--dd-icons); background-repeat: no-repeat; image-rendering: pixelated; vertical-align: middle; }

/* Buttons: white, rounded, and they press down. */
.dd-btn {
    font-family: inherit; font-weight: 800; font-size: 12px; line-height: 1.15; color: var(--dd-text);
    background: var(--dd-panel); border: 2px solid var(--dd-line); border-radius: 12px; padding: 5px 11px;
    box-shadow: 0 3px 0 var(--dd-line); cursor: pointer; white-space: nowrap;
    display: inline-flex; align-items: center; justify-content: center; gap: 5px;
    transition: transform 0.08s ease, box-shadow 0.08s ease, border-color 0.15s ease, background 0.15s ease;
}
.dd-btn:hover { border-color: var(--dd-primary); box-shadow: 0 3px 0 var(--dd-primary-line); transform: translateY(-1px); }
.dd-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--dd-line); }
.dd-btn:focus { outline: none; }
/* MZ's NW.js is Chromium 85: no :focus-visible, and a rule list naming it is dropped whole. So each ring is a
   rule of its own, twinned by a plain :focus one that a mouse press turns off (dd-mouse-focus, Ui.watchFocusSource). */
.dd-btn:focus-visible { box-shadow: 0 0 0 3px rgba(46, 155, 255, 0.45), 0 3px 0 var(--dd-line); }
:root:not(.dd-mouse-focus) .dd-btn:focus { box-shadow: 0 0 0 3px rgba(46, 155, 255, 0.45), 0 3px 0 var(--dd-line); }
.dd-btn:disabled { opacity: 0.5; cursor: default; transform: none; }
.dd-btn-primary { background: var(--dd-primary); border-color: var(--dd-primary-dark); color: #fff; box-shadow: 0 3px 0 var(--dd-primary-dark); }
.dd-btn-primary:hover { background: #45a8ff; border-color: var(--dd-primary-dark); box-shadow: 0 3px 0 var(--dd-primary-dark); }
.dd-btn-good { background: var(--dd-good); border-color: var(--dd-good-dark); color: #fff; box-shadow: 0 3px 0 var(--dd-good-dark); }
.dd-btn-good:hover { background: #45cf7d; border-color: var(--dd-good-dark); box-shadow: 0 3px 0 var(--dd-good-dark); }
.dd-btn-danger { background: var(--dd-danger); border-color: var(--dd-danger-dark); color: #fff; box-shadow: 0 3px 0 var(--dd-danger-dark); }
.dd-btn-danger:hover { background: #ff7175; border-color: var(--dd-danger-dark); box-shadow: 0 3px 0 var(--dd-danger-dark); }
.dd-btn-active, .dd-btn.dd-btn-active {
    background: var(--dd-warn-soft) !important; border-color: #f2b600 !important; color: var(--dd-text) !important;
    box-shadow: 0 3px 0 #e0a800 !important; animation: dd-pop 0.22s ease;
}

/* The top bar: big icon tools with a word under each, like a game's build menu. */
#dd-toolbar { display: flex; align-items: center; gap: 4px; padding: 5px 8px; }
#dd-toolbar .dd-brand { display: flex; align-items: center; gap: 4px; padding: 0 6px 0 2px; font-weight: 900; font-size: 15px; color: var(--dd-good-dark); letter-spacing: 0.2px; }
#dd-toolbar .dd-sep { width: 2px; align-self: stretch; margin: 6px 3px; background: var(--dd-line-soft); border-radius: 2px; }
#dd-toolbar .dd-spacer { flex: 1; }
.dd-tool { flex-direction: column; gap: 1px; width: 54px; height: 54px; padding: 3px 2px 2px; border-radius: 14px; font-size: 10px; }
.dd-tool b { font-weight: 800; font-size: 10px; }
.dd-tool.dd-wide { width: 62px; }
@media (max-width: 900px) { #dd-toolbar .dd-brand span { display: none; } .dd-tool { width: 46px; } .dd-tool.dd-wide { width: 52px; } }
/* Save: an orange dot while something isn't saved, a tick-green flash once it is. */
#dd-save-btn { position: relative; }
#dd-save-btn.dd-unsaved::after {
    content: ''; position: absolute; top: 3px; right: 4px; width: 11px; height: 11px; border-radius: 50%;
    background: var(--dd-warn); border: 2px solid var(--dd-panel); animation: dd-pop 0.22s ease;
}
#dd-save-btn.dd-just-saved { animation: dd-pop 0.3s ease; filter: brightness(1.08); }

/* Pop-up option cards (brush settings, path, mirror, More). */
.dd-pop { position: absolute; z-index: 10015; width: 270px; padding: 12px 14px; animation: dd-rise 0.18s ease; }
.dd-pop-title { display: flex; align-items: center; gap: 6px; font-weight: 900; font-size: 13px; color: var(--dd-text) !important; margin-bottom: 8px; }
#dd-more-menu { width: 300px; }
.dd-more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.dd-more-grid .dd-btn { justify-content: flex-start; padding: 6px 8px; height: 40px; }

/* Panels: the bag (left) and details (right) fold away to give the map room. */
.dd-panel-head { display: flex; align-items: center; gap: 6px; font-weight: 900; font-size: 14px; color: var(--dd-text); }
.dd-panel-head .dd-grow { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dd-fold { width: 30px; height: 30px; padding: 0; border-radius: 10px; flex: none; }
.dd-collapsed { width: 52px !important; bottom: auto !important; padding: 8px 6px !important; overflow: hidden !important; cursor: pointer; }
.dd-collapsed > :not(.dd-panel-head) { display: none !important; }
.dd-collapsed .dd-panel-head { flex-direction: column; }
.dd-collapsed .dd-panel-head .dd-grow, .dd-collapsed .dd-panel-head .dd-hide-folded { display: none; }
.dd-tab-chip { flex-wrap: wrap; }
#dd-category-tabs { display: flex; flex-wrap: wrap; gap: 3px; }
#dd-category-tabs .dd-btn { width: 28px; height: 28px; padding: 0; border-radius: 9px; }
.dd-search { position: relative; flex: 1; min-width: 0; }
.dd-search .dd-ico { position: absolute; left: 7px; top: 50%; margin-top: -8px; pointer-events: none; }
.dd-search input { width: 100%; padding-left: 28px !important; height: 32px; border-radius: 16px !important; }

/* Item cards. */
.dd-card {
    background: var(--dd-panel); border: 2px solid var(--dd-line); border-radius: 14px; box-shadow: 0 3px 0 var(--dd-line);
    cursor: pointer; position: relative; overflow: hidden; color: var(--dd-text);
    transition: transform 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
}
.dd-card img, .dd-card canvas {
    border-radius: 8px;
    background-color: var(--dd-check-a);
    background-image: linear-gradient(45deg, var(--dd-check-b) 25%, transparent 25%, transparent 75%, var(--dd-check-b) 75%), linear-gradient(45deg, var(--dd-check-b) 25%, transparent 25%, transparent 75%, var(--dd-check-b) 75%);
    background-size: 12px 12px; background-position: 0 0, 6px 6px;
}
.dd-card:hover { transform: translateY(-2px); border-color: var(--dd-primary); box-shadow: 0 4px 0 var(--dd-primary-line); }
.dd-card.selected { border-color: var(--dd-primary); box-shadow: 0 0 0 3px rgba(46, 155, 255, 0.35), 0 3px 0 var(--dd-primary-dark); animation: dd-pop 0.22s ease; }
.dd-card > div { color: var(--dd-text) !important; font-weight: 700; }
.dd-badge { position: absolute; top: 4px; right: 4px; background: var(--dd-warn-soft); border: 2px solid #f2b600; padding: 0 5px; border-radius: 10px; font-size: 10px; color: var(--dd-warn); font-weight: 900; }

/* Fields. */
#dd-asset-workspace-root input[type=text], #dd-asset-workspace-root input[type=number], #dd-asset-workspace-root input[type=search],
#dd-asset-workspace-root select, #dd-asset-workspace-root textarea,
.dd-glass input[type=text], .dd-glass input[type=number], .dd-glass input[type=search], .dd-glass select, .dd-glass textarea {
    font-family: inherit; font-weight: 700; font-size: 12px; color: var(--dd-text) !important;
    background: var(--dd-field) !important; border: 2px solid var(--dd-line) !important; border-radius: 10px !important;
    padding: 4px 8px; outline: none; min-height: 28px;
}
#dd-asset-workspace-root input:focus, #dd-asset-workspace-root select:focus, #dd-asset-workspace-root textarea:focus,
.dd-glass input:focus, .dd-glass select:focus, .dd-glass textarea:focus {
    border-color: var(--dd-primary) !important; background: var(--dd-panel) !important; box-shadow: 0 0 0 3px rgba(46, 155, 255, 0.22);
}
.dd-glass input[type=color], #dd-asset-workspace-root input[type=color] {
    -webkit-appearance: none; border: 2px solid var(--dd-line) !important; border-radius: 10px; padding: 2px; background: var(--dd-panel) !important; height: 28px; cursor: pointer;
}
.dd-glass input[type=color]::-webkit-color-swatch-wrapper { padding: 0; }
.dd-glass input[type=color]::-webkit-color-swatch { border: none; border-radius: 7px; }
.dd-glass label { color: var(--dd-muted); }

/* Sliders. */
.dd-glass input[type=range] { -webkit-appearance: none; height: 22px; background: transparent !important; border: none !important; padding: 0; cursor: pointer; }
.dd-glass input[type=range]:focus { box-shadow: none; }
.dd-glass input[type=range]::-webkit-slider-runnable-track { height: 8px; border-radius: 8px; background: var(--dd-line); }
.dd-glass input[type=range]::-webkit-slider-thumb {
    -webkit-appearance: none; width: 18px; height: 18px; margin-top: -5px; border-radius: 50%;
    background: #ffffff; border: 3px solid var(--dd-primary); box-shadow: 0 2px 0 var(--dd-primary-dark);
}
.dd-glass input[type=range]:active::-webkit-slider-thumb { transform: scale(1.15); }

/* Check boxes are on/off switches; radios are round. */
.dd-glass input[type=checkbox] {
    -webkit-appearance: none; width: 34px; height: 20px; margin: 0 2px; border-radius: 20px; flex: none; vertical-align: middle;
    background: var(--dd-switch-off); border: 2px solid var(--dd-switch-line); position: relative; cursor: pointer; transition: background 0.15s ease, border-color 0.15s ease;
}
.dd-glass input[type=checkbox]::after {
    content: ''; position: absolute; top: 1px; left: 1px; width: 14px; height: 14px; border-radius: 50%;
    background: #ffffff; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3); transition: left 0.15s ease;
}
.dd-glass input[type=checkbox]:checked { background: var(--dd-good); border-color: var(--dd-good-dark); }
.dd-glass input[type=checkbox]:checked::after { left: 15px; }
.dd-glass input[type=radio] {
    -webkit-appearance: none; width: 16px; height: 16px; margin: 0 2px; border-radius: 50%; flex: none; vertical-align: middle;
    background: var(--dd-panel); border: 2px solid var(--dd-switch-line); cursor: pointer;
}
.dd-glass input[type=radio]:checked { border: 5px solid var(--dd-primary); }

/* Sections fold open like cards. */
.dd-glass details {
    background: var(--dd-panel-2); border: 2px solid var(--dd-line-soft) !important; border-radius: 14px;
    padding: 6px 10px !important; margin-top: 8px !important;
}
.dd-glass details[open] { background: var(--dd-panel); border-color: var(--dd-line) !important; }
.dd-glass summary {
    list-style: none; cursor: pointer; display: flex; align-items: center; gap: 6px;
    font-weight: 900 !important; font-size: 12px !important; color: var(--dd-text) !important; padding: 2px 0;
}
.dd-glass summary::-webkit-details-marker { display: none; }
.dd-glass summary::before {
    content: ''; flex: none; width: 0; height: 0; border-left: 7px solid var(--dd-primary);
    border-top: 5px solid transparent; border-bottom: 5px solid transparent; transition: transform 0.15s ease;
}
.dd-glass details[open] > summary::before { transform: rotate(90deg); }

/* Scroll bars. */
.dd-glass ::-webkit-scrollbar, #dd-asset-workspace-root ::-webkit-scrollbar { width: 10px; height: 10px; }
.dd-glass ::-webkit-scrollbar-thumb, #dd-asset-workspace-root ::-webkit-scrollbar-thumb { background: var(--dd-scroll); border-radius: 10px; border: 2px solid var(--dd-panel); }
.dd-glass ::-webkit-scrollbar-track { background: transparent; }

/* Panel insides: labels, and buttons that wrap rather than spill out of narrow panels. */
.dd-label { font-size: 11px; font-weight: 900; color: var(--dd-muted); margin: 2px 0 5px; }
#dd-inspector-content .dd-btn, .dd-glass details .dd-btn { white-space: normal; min-width: 0; text-align: center; }
#dd-inspector-content [style*="display: flex"] { flex-wrap: wrap; }
#dd-inspector-content label[style*="display: flex"] { flex-wrap: nowrap; }
#dd-inspector-content > div[style*="border-top"], .dd-glass > div[style*="border-top"] { border-top: 2px solid var(--dd-line-soft) !important; }

/* The hint bubble, toasts and menus. */
#dd-hint {
    position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%); max-width: min(560px, calc(100vw - 140px));
    display: flex; align-items: center; gap: 8px; padding: 6px 14px 6px 8px; border-radius: 22px; font-size: 12px; font-weight: 700;
}
#dd-hint #dd-status-left { color: var(--dd-text); }
.dd-toast {
    position: fixed; top: 84px; left: 50%; transform: translateX(-50%); z-index: 10030; pointer-events: none;
    display: flex; align-items: center; gap: 8px; padding: 8px 16px 8px 10px; border-radius: 22px;
    font-family: var(--dd-font); font-size: 13px; font-weight: 800; color: var(--dd-text); background: var(--dd-panel);
    border: 3px solid var(--dd-primary); box-shadow: 0 4px 0 var(--dd-primary-dark), 0 10px 24px rgba(20, 16, 40, 0.3);
    animation: dd-bounce 0.35s ease; transition: opacity 0.3s ease;
}
.dd-toast.dd-toast-success { border-color: var(--dd-good); box-shadow: 0 4px 0 var(--dd-good-dark), 0 10px 24px rgba(20, 16, 40, 0.3); }
.dd-toast.dd-toast-error { border-color: var(--dd-danger); box-shadow: 0 4px 0 var(--dd-danger-dark), 0 10px 24px rgba(20, 16, 40, 0.3); }
#dd-context-menu { padding: 6px; border-radius: 16px; min-width: 200px; }
#dd-context-menu .dd-btn { border: none; box-shadow: none; background: transparent; justify-content: flex-start; border-radius: 10px; padding: 6px 10px; font-size: 12px; }
#dd-context-menu .dd-btn:hover { background: var(--dd-primary-soft); transform: none; }
#dd-context-menu .dd-btn.dd-danger { color: var(--dd-danger-dark); }
#dd-context-menu .dd-btn.dd-danger:hover { background: var(--dd-danger-soft); }
#dd-context-menu .dd-menu-sep { height: 2px; background: var(--dd-line-soft); margin: 4px 6px; border-radius: 2px; }

/* The welcome card. */
#dd-welcome { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 380px; max-width: calc(100vw - 32px); padding: 18px 20px; z-index: 10040; animation: dd-bounce 0.4s ease; text-align: center; }
#dd-welcome h2 { margin: 6px 0 4px; font-size: 20px; font-weight: 900; color: var(--dd-text); }
#dd-welcome ol { text-align: left; margin: 10px 0 14px; padding-left: 0; list-style: none; display: flex; flex-direction: column; gap: 8px; }
#dd-welcome li { display: flex; align-items: center; gap: 10px; background: var(--dd-panel-2); border-radius: 14px; padding: 6px 10px; font-size: 13px; font-weight: 700; }
#dd-welcome li .dd-num { width: 24px; height: 24px; border-radius: 50%; background: var(--dd-primary); color: #fff; display: inline-flex; align-items: center; justify-content: center; font-weight: 900; flex: none; }

@keyframes dd-pop { 0% { transform: scale(0.92); } 60% { transform: scale(1.06); } 100% { transform: scale(1); } }
@keyframes dd-bounce { 0% { opacity: 0; transform: translate(-50%, 12px) scale(0.9); } 60% { opacity: 1; transform: translate(-50%, -3px) scale(1.03); } 100% { transform: translate(-50%, 0) scale(1); } }
#dd-welcome { animation-name: dd-bounce-center; }
@keyframes dd-bounce-center { 0% { opacity: 0; transform: translate(-50%, -46%) scale(0.9); } 60% { opacity: 1; transform: translate(-50%, -51%) scale(1.03); } 100% { transform: translate(-50%, -50%) scale(1); } }
@keyframes dd-rise { 0% { opacity: 0; transform: translateY(-6px); } 100% { opacity: 1; transform: translateY(0); } }
`,

    // The look for the page: the editor's font, then the stylesheet with the icon sheet in it.
    // (Letters the font doesn't have, such as Japanese, come from MZ's own rmmz-mainfont.)
    styleText() {
        const url = DocsDoodads.UiIcons ? DocsDoodads.UiIcons.url : '';
        const fonts = DocsDoodads.UiFonts ? DocsDoodads.UiFonts.css + '\n' : '';
        return fonts + this.css.replace(':root {', `:root {\n    --dd-icons: url(${url});`);
    },

    // Where focus came from, for the :focus rings above: a press marks the page, moving with the keys
    // (Tab, F6, arrows) clears it. Other keys leave it, so a shortcut doesn't ring the button last clicked.
    focusKeys: ['Tab', 'F6', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'],

    watchFocusSource() {
        if (this._focusWatch || typeof document === 'undefined' || typeof document.addEventListener !== 'function') return false;
        const root = document.documentElement;
        if (!root || !root.classList) return false;
        const press = () => root.classList.add('dd-mouse-focus');
        const key = e => { if (e && this.focusKeys.includes(e.key)) root.classList.remove('dd-mouse-focus'); };
        document.addEventListener('pointerdown', press, true);
        document.addEventListener('mousedown', press, true);
        document.addEventListener('keydown', key, true);
        this._focusWatch = { press, key };
        return true;
    }
};

//==========================================================
// SECTION 24d: DocsDoodads.Ui DIALOGS (QUESTION CARDS)
//==========================================================
// The editor's own cards in place of the browser's prompt, confirm and alert: they match the look, fit a
// small window, close with Esc (the cancel answer) and answer with Enter (the main button). Each returns
// a promise. One card at a time: opening another gives the one showing its cancel answer.
DocsDoodads.Ui.css += `
/* Question cards (names, confirmations, unsaved work). */
#dd-dialog-overlay {
    position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 10060; display: flex; align-items: center; justify-content: center;
    background: rgba(31, 27, 48, 0.35); pointer-events: auto; font-family: var(--dd-font);
}
.dd-dialog { width: 400px; max-width: calc(100vw - 32px); max-height: calc(100vh - 32px); overflow: auto; padding: 16px 18px; animation: dd-pop 0.22s ease; }
.dd-dialog .dd-pop-title { font-size: 15px; margin-bottom: 6px; }
.dd-dialog-text { font-size: 13px; font-weight: 700; line-height: 1.5; color: var(--dd-text); white-space: pre-line; margin-bottom: 12px; overflow-wrap: anywhere; }
.dd-dialog-field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 10px; }
.dd-dialog-field input[type=text], .dd-dialog-field select { width: 100%; height: 34px; font-size: 13px !important; }
.dd-dialog-check { flex-direction: row; align-items: center; gap: 8px; font-size: 12px; color: var(--dd-text) !important; }
.dd-dialog-buttons { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 4px; }
.dd-dialog-buttons .dd-btn { min-width: 84px; padding: 7px 12px; font-size: 13px; }
.dd-dialog-stack .dd-dialog-buttons { flex-direction: column; align-items: stretch; }
.dd-dialog-danger { border-color: var(--dd-danger); }
.dd-dialog-danger .dd-pop-title { color: var(--dd-danger-dark) !important; }
`;

Object.assign(DocsDoodads.Ui, {
    _dialog: null,

    dialogOpen() {
        return Boolean(this._dialog);
    },

    // opts: { title, text, icon, tone ('danger'), stack (buttons one above the other), fields: [{ key, label, value, type ('text' | 'checkbox' |
    // 'select'), choices (suggestions for text), options ([{ value, label }] for select), placeholder }], buttons: [{ label, value, kind ('primary' | 'good' | 'danger'), main }],
    // cancelValue }. Resolves { button, values }: the button's value (cancelValue for Esc or a click
    // outside the card) and each field's value by key.
    dialog(opts = {}) {
        if (typeof document === 'undefined' || !document.createElement) {
            return Promise.resolve({ button: opts.cancelValue === undefined ? null : opts.cancelValue, values: {} });
        }
        if (this._dialog) this._dialog.finish(this._dialog.cancelValue, true);
        const U = this;
        const cancelValue = opts.cancelValue === undefined ? null : opts.cancelValue;
        const buttons = (opts.buttons && opts.buttons.length) ? opts.buttons : [{ label: 'OK', value: true, kind: 'primary' }];
        const main = buttons.find(b => b.main) || buttons.slice().reverse().find(b => b.value !== cancelValue) || buttons[buttons.length - 1];
        const make = (tag, className, text) => {
            const n = document.createElement(tag);
            if (className) n.className = className;
            if (text !== undefined) n.textContent = String(text);
            return n;
        };

        const overlay = make('div');
        overlay.id = 'dd-dialog-overlay';
        const card = make('div', 'dd-glass dd-dialog' + (opts.tone === 'danger' ? ' dd-dialog-danger' : '') + (opts.stack ? ' dd-dialog-stack' : ''));
        card.id = 'dd-dialog';
        if (card.setAttribute) {
            card.setAttribute('role', opts.tone === 'danger' ? 'alertdialog' : 'dialog');
            card.setAttribute('aria-modal', 'true');
            card.setAttribute('aria-labelledby', 'dd-dialog-title');
        }
        // The theme lives in the workspace; a card shown with the editor closed brings its own copy.
        const themed = document.getElementById && document.getElementById('dd-ui-style');
        if (!themed || themed.isConnected === false) {
            const style = make('style');
            style.textContent = this.styleText();
            overlay.appendChild(style);
        }
        if (this.watchFocusSource) this.watchFocusSource();

        const title = make('div', 'dd-pop-title');
        title.id = 'dd-dialog-title';
        title.innerHTML = this.icon(opts.icon || (opts.tone === 'danger' ? 'trash' : 'help'), 1);
        title.appendChild(make('span', '', opts.title || "Doc's Doodads"));
        card.appendChild(title);
        if (opts.text) {
            const text = make('div', 'dd-dialog-text', opts.text);
            text.id = 'dd-dialog-text';
            card.appendChild(text);
            if (card.setAttribute) card.setAttribute('aria-describedby', 'dd-dialog-text');
        }

        const inputs = [];
        (opts.fields || []).forEach((field, i) => {
            const id = 'dd-dialog-field-' + i;
            const wrap = make(field.type === 'checkbox' ? 'label' : 'div', 'dd-dialog-field' + (field.type === 'checkbox' ? ' dd-dialog-check' : ''));
            const input = make(field.type === 'select' ? 'select' : 'input');
            input.id = id;
            if (field.type === 'select') {
                for (const choice of field.options || []) {
                    const option = make('option', '', choice.label !== undefined ? choice.label : choice.value);
                    option.value = String(choice.value);
                    input.appendChild(option);
                }
                input.value = field.value === undefined ? '' : String(field.value);
                if (field.label) {
                    const label = make('label', 'dd-label', field.label);
                    if (label.setAttribute) label.setAttribute('for', id);
                    wrap.appendChild(label);
                }
                wrap.appendChild(input);
            } else if (field.type === 'checkbox') {
                input.type = 'checkbox';
                input.checked = Boolean(field.value);
                wrap.appendChild(input);
                wrap.appendChild(make('span', '', field.label || ''));
            } else {
                input.type = 'text';
                input.value = field.value === undefined || field.value === null ? '' : String(field.value);
                if (field.placeholder) input.placeholder = field.placeholder;
                if (field.label) {
                    const label = make('label', 'dd-label', field.label);
                    if (label.setAttribute) label.setAttribute('for', id);
                    wrap.appendChild(label);
                }
                wrap.appendChild(input);
                if (field.choices && field.choices.length) {
                    const list = make('datalist');
                    list.id = id + '-choices';
                    for (const choice of field.choices) {
                        const option = make('option');
                        option.value = String(choice);
                        list.appendChild(option);
                    }
                    wrap.appendChild(list);
                    if (input.setAttribute) input.setAttribute('list', list.id);
                }
            }
            inputs.push({ field, input });
            card.appendChild(wrap);
        });

        const row = make('div', 'dd-dialog-buttons');
        const buttonEls = buttons.map(b => {
            const btn = make('button', 'dd-btn' + (b.kind ? ' dd-btn-' + b.kind : ''), b.label);
            btn.type = 'button';
            btn.onclick = () => finish(b.value);
            row.appendChild(btn);
            return btn;
        });
        card.appendChild(row);
        overlay.appendChild(card);
        overlay.onclick = e => { if (e && e.target === overlay) finish(cancelValue); };

        const before = document.activeElement || null;
        const values = () => {
            const out = {};
            inputs.forEach(({ field, input }, i) => {
                out[field.key || i] = field.type === 'checkbox' ? Boolean(input.checked) : String(input.value || '');
            });
            return out;
        };
        // Every key goes to the card while it shows: the editor and the game don't see them.
        const onKey = e => {
            if (e.stopPropagation) e.stopPropagation();
            if (e.key === 'Escape') {
                if (e.preventDefault) e.preventDefault();
                finish(cancelValue);
            } else if (e.key === 'Enter') {
                if (e.target && e.target.tagName === 'BUTTON') return; // the focused button answers
                if (e.preventDefault) e.preventDefault();
                finish(main.value);
            } else if (e.key === 'Tab') {
                // Tab stays inside the card.
                const order = inputs.map(x => x.input).concat(buttonEls);
                const at = order.indexOf(document.activeElement);
                const next = e.shiftKey ? (at <= 0 ? order.length - 1 : at - 1) : (at < 0 || at >= order.length - 1 ? 0 : at + 1);
                if (order[next] && order[next].focus) {
                    if (e.preventDefault) e.preventDefault();
                    order[next].focus();
                }
            }
        };

        let resolve;
        const promise = new Promise(r => { resolve = r; });
        let done = false;
        function finish(value, quiet) {
            if (done) return;
            done = true;
            const result = { button: value, values: values() };
            if (document.removeEventListener) document.removeEventListener('keydown', onKey, true);
            if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
            if (U._dialog && U._dialog.finish === finish) U._dialog = null;
            if (!quiet) U.sound(value === cancelValue ? 'cancel' : 'ok');
            if (before && before.focus && before.isConnected !== false) {
                try { before.focus(); } catch (e) {}
            }
            resolve(result);
        }
        this._dialog = { finish, cancelValue, overlay, card, buttons: buttonEls, inputs: inputs.map(x => x.input) };

        if (document.addEventListener) document.addEventListener('keydown', onKey, true);
        (document.body || document.documentElement).appendChild(overlay);
        if (opts.tone === 'danger') this.sound('buzzer');
        const first = inputs.length ? inputs[0].input : buttonEls[buttons.indexOf(main)];
        if (first && first.focus) {
            try {
                first.focus();
                if (first.select && first.type === 'text') first.select();
            } catch (e) {}
        }
        return promise;
    },

    // Yes or no. opts: { title, ok, cancel, danger }. A danger question gets a red button.
    confirm(text, opts = {}) {
        return this.dialog({
            title: opts.title || (opts.danger ? 'Are you sure?' : 'Please check'),
            text, icon: opts.icon, tone: opts.danger ? 'danger' : undefined, cancelValue: false,
            buttons: [
                { label: opts.cancel || 'Cancel', value: false },
                { label: opts.ok || 'OK', value: true, kind: opts.danger ? 'danger' : 'primary' }
            ]
        }).then(r => r.button === true);
    },

    // A line of text, or null when cancelled. opts: { title, ok, choices, placeholder, label }.
    prompt(text, value = '', opts = {}) {
        return this.form({
            title: opts.title, text, ok: opts.ok, icon: opts.icon || 'wrench',
            fields: [{ key: 'value', value, choices: opts.choices, placeholder: opts.placeholder, label: opts.label }]
        }).then(values => values ? values.value : null);
    },

    // Several fields at once: their values by key, or null when cancelled. opts: { title, text, fields, ok, danger }.
    form(opts = {}) {
        return this.dialog({
            title: opts.title || 'Name it', text: opts.text, icon: opts.icon || 'wrench',
            tone: opts.danger ? 'danger' : undefined, fields: opts.fields || [], cancelValue: false,
            buttons: [
                { label: opts.cancel || 'Cancel', value: false },
                { label: opts.ok || 'OK', value: true, kind: opts.danger ? 'danger' : 'primary' }
            ]
        }).then(r => r.button === true ? r.values : null);
    },

    // A message with one button.
    alert(text, opts = {}) {
        return this.dialog({
            title: opts.title || 'Note', text, icon: opts.icon || 'info',
            buttons: [{ label: opts.ok || 'OK', value: true, kind: 'primary' }], cancelValue: true
        }).then(() => undefined);
    },

    // Pick one of several answers: resolves the chosen button's value (or cancelValue for Esc).
    choose(text, buttons, opts = {}) {
        return this.dialog(Object.assign({ text, buttons }, opts)).then(r => r.button);
    }
});

//==========================================================
// SECTION 24e: DocsDoodads.Ui FEEDBACK (PROGRESS PILLS, TOOLTIPS)
//==========================================================
// Long jobs (indexing, packing, Auto-Slice, importing) show a small pill with a bar and Cancel, all in
// one place, and never block the editor. Buttons get a themed tooltip with their shortcut after a moment.
DocsDoodads.Ui.css += `
/* Progress pills: top right of the map. */
#dd-progress-stack { position: fixed; top: 84px; right: 16px; z-index: 10024; display: flex; flex-direction: column; gap: 6px; align-items: flex-end; pointer-events: none; }
.dd-progress {
    pointer-events: auto; display: flex; align-items: center; gap: 8px; min-width: 220px; max-width: 320px; padding: 6px 6px 6px 12px;
    border-radius: 18px; font-family: var(--dd-font); font-size: 11px; font-weight: 800; color: var(--dd-text); background: var(--dd-panel);
    border: 2px solid var(--dd-line); box-shadow: 0 3px 0 var(--dd-line), 0 8px 20px rgba(20, 16, 40, 0.22); animation: dd-rise 0.18s ease;
}
.dd-progress .dd-progress-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.dd-progress .dd-progress-label { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dd-progress .dd-progress-track { height: 6px; border-radius: 6px; background: var(--dd-line-soft); overflow: hidden; }
.dd-progress .dd-progress-bar { height: 100%; width: 0%; border-radius: 6px; background: var(--dd-primary); transition: width 0.2s ease; }
.dd-progress.dd-progress-unknown .dd-progress-bar { width: 35%; animation: dd-progress-slide 1.1s ease-in-out infinite; }
.dd-progress .dd-btn { padding: 3px 9px; font-size: 11px; border-radius: 12px; }
@keyframes dd-progress-slide { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }

/* Tooltips: the button's name, and its shortcut in a key cap. */
#dd-tooltip {
    position: fixed; z-index: 10070; pointer-events: none; max-width: 280px; padding: 5px 9px; border-radius: 10px;
    font-family: var(--dd-font); font-size: 11px; font-weight: 800; line-height: 1.35; color: #ffffff; background: rgba(31, 27, 48, 0.92);
    box-shadow: 0 6px 16px rgba(20, 16, 40, 0.3); animation: dd-rise 0.12s ease;
}
#dd-tooltip kbd {
    display: inline-block; margin-left: 6px; padding: 0 5px; border-radius: 5px; font-family: inherit; font-size: 10px; font-weight: 900;
    color: #2f2a43; background: #ffffff; box-shadow: 0 2px 0 #b9b3cc;
}
`;

Object.assign(DocsDoodads.Ui, {
    // ---- Progress pills ----
    // label: what is happening. opts: { onCancel (shows Cancel), delay (ms before the pill shows, so quick
    // jobs never flash one) }. Returns { update(done, total, text), finish(), cancelled }.
    progress(label, opts = {}) {
        const U = this;
        const handle = {
            label, done: 0, total: 0, text: '', cancelled: false, finished: false, el: null,
            update(done, total, text) {
                this.done = Number(done) || 0;
                this.total = Number(total) || 0;
                if (text !== undefined) this.text = String(text);
                U.drawProgress(this);
                return this;
            },
            cancel() {
                if (this.cancelled || this.finished) return;
                this.cancelled = true;
                this.text = 'Cancelling…';
                U.drawProgress(this);
                if (typeof opts.onCancel === 'function') opts.onCancel();
            },
            finish() {
                this.finished = true;
                clearTimeout(this._timer);
                if (this.el && this.el.parentNode) this.el.parentNode.removeChild(this.el);
                this.el = null;
                U._progress = (U._progress || []).filter(h => h !== this);
                return this;
            }
        };
        handle.cancellable = typeof opts.onCancel === 'function';
        this._progress = (this._progress || []).concat([handle]);
        const show = () => { if (!handle.finished) { handle.shown = true; U.drawProgress(handle); } };
        if (opts.delay > 0) handle._timer = setTimeout(show, opts.delay); else show();
        if (handle._timer && typeof handle._timer.unref === 'function') handle._timer.unref();
        return handle;
    },

    activeProgress() {
        return (this._progress || []).slice();
    },

    progressText(h) {
        const count = h.total > 0 ? ` ${Math.min(h.done, h.total)}/${h.total}` : '';
        return h.text ? `${h.label}${count} · ${h.text}` : `${h.label}${count}`;
    },

    drawProgress(h) {
        if (!h.shown || h.finished || typeof document === 'undefined' || !document.createElement) return;
        let stack = document.getElementById('dd-progress-stack');
        if (!stack) {
            stack = document.createElement('div');
            stack.id = 'dd-progress-stack';
            (document.body || document.documentElement).appendChild(stack);
            const W = DocsDoodads.Workspace;
            if (W && W.placeReadouts) W.placeReadouts();
        }
        if (!h.el) {
            const el = document.createElement('div');
            el.className = 'dd-progress';
            const bodyEl = document.createElement('div');
            bodyEl.className = 'dd-progress-body';
            const labelEl = document.createElement('div');
            labelEl.className = 'dd-progress-label';
            const track = document.createElement('div');
            track.className = 'dd-progress-track';
            const bar = document.createElement('div');
            bar.className = 'dd-progress-bar';
            track.appendChild(bar);
            bodyEl.appendChild(labelEl);
            bodyEl.appendChild(track);
            el.appendChild(bodyEl);
            if (h.cancellable) {
                const btn = document.createElement('button');
                btn.className = 'dd-btn';
                btn.type = 'button';
                btn.textContent = 'Cancel';
                btn.onclick = () => h.cancel();
                el.appendChild(btn);
                h.cancelButton = btn;
            }
            if (el.setAttribute) { el.setAttribute('role', 'progressbar'); el.setAttribute('aria-label', h.label); }
            stack.appendChild(el);
            h.el = el; h.labelEl = labelEl; h.barEl = bar;
        }
        h.labelEl.textContent = this.progressText(h);
        const known = h.total > 0;
        if (h.el.classList) h.el.classList.toggle('dd-progress-unknown', !known);
        h.barEl.style.width = known ? Math.round(Math.min(1, h.done / h.total) * 100) + '%' : '';
        if (h.el.setAttribute && known) h.el.setAttribute('aria-valuenow', String(Math.round(Math.min(1, h.done / h.total) * 100)));
        if (h.cancelButton) h.cancelButton.disabled = h.cancelled;
    },

    // ---- Tooltips ----
    // The shortcut at the end of a title, "Save everything (Ctrl+S)" -> ['Save everything', 'Ctrl+S'].
    splitTip(title) {
        const text = String(title || '').trim();
        const m = /^(.*\S)\s*\(([^()]+)\)$/.exec(text);
        const isKey = k => /^((Ctrl|Shift|Alt)\s*\+\s*)*([A-Z0-9`\[\]]|F\d{1,2}|Esc|Del|Delete|Enter|Space|Tab|Backspace)$/.test(k);
        if (m && isKey(m[2].trim())) return [m[1].replace(/[:\s]+$/, ''), m[2].trim().replace(/\s*\+\s*/g, '+')];
        return [text, ''];
    },

    // Editor elements with a title show it as a themed tooltip after a short rest (the browser's own
    // tooltip is turned off by moving the title to data-dd-tip; screen readers keep it as aria-label).
    tooltipDelay: 450,

    tipTarget(target) {
        if (!target || typeof target.closest !== 'function') return null;
        const el = target.closest('[title], [data-dd-tip]');
        if (!el || !el.closest('#dd-asset-workspace-root, .dd-glass, #dd-dialog-overlay')) return null;
        if (el.hasAttribute && el.hasAttribute('title')) {
            const title = el.getAttribute('title');
            el.removeAttribute('title');
            if (title) {
                el.setAttribute('data-dd-tip', title);
                if (!el.hasAttribute('aria-label') && !String(el.textContent || '').trim()) el.setAttribute('aria-label', title);
            }
        }
        return el.getAttribute && el.getAttribute('data-dd-tip') ? el : null;
    },

    showTooltip(el) {
        if (typeof document === 'undefined' || !el || !el.getAttribute) return null;
        this.hideTooltip();
        const [text, keys] = this.splitTip(el.getAttribute('data-dd-tip'));
        if (!text) return null;
        const tip = document.createElement('div');
        tip.id = 'dd-tooltip';
        tip.textContent = text;
        if (keys) {
            const kbd = document.createElement('kbd');
            kbd.textContent = keys;
            tip.appendChild(kbd);
        }
        (document.body || document.documentElement).appendChild(tip);
        let r = el.getBoundingClientRect ? el.getBoundingClientRect() : { left: 0, right: 0, top: 0, bottom: 0 };
        // Inside the zoomed workspace, rects are in its own units: to window pixels.
        const s = el.closest && el.closest('#dd-asset-workspace-root') && this.uiScale ? this.uiScale() : 1;
        if (s !== 1) r = { left: r.left * s, right: r.right * s, top: r.top * s, bottom: r.bottom * s };
        const roomW = (typeof window !== 'undefined' && window.innerWidth) || 816;
        const roomH = (typeof window !== 'undefined' && window.innerHeight) || 624;
        const w = tip.offsetWidth || 160, h = tip.offsetHeight || 24;
        const below = r.bottom + 8 + h < roomH;
        tip.style.left = Math.round(Math.max(6, Math.min(roomW - w - 6, (r.left + r.right) / 2 - w / 2))) + 'px';
        tip.style.top = Math.round(below ? r.bottom + 8 : Math.max(6, r.top - h - 8)) + 'px';
        this._tooltip = { tip, el };
        return tip;
    },

    hideTooltip() {
        clearTimeout(this._tipTimer);
        const t = this._tooltip;
        this._tooltip = null;
        if (t && t.tip.parentNode) t.tip.parentNode.removeChild(t.tip);
    },

    installTooltips() {
        if (this._tipHandlers || typeof document === 'undefined' || !document.addEventListener) return;
        const over = e => {
            const el = this.tipTarget(e.target);
            if (!el) { if (this._tooltip || this._tipFor) { this._tipFor = null; this.hideTooltip(); } return; }
            if (this._tipFor === el) return;
            this._tipFor = el;
            this.hideTooltip();
            this._tipTimer = setTimeout(() => { if (this._tipFor === el && el.isConnected !== false) this.showTooltip(el); }, this.tooltipDelay);
        };
        const away = () => { this._tipFor = null; this.hideTooltip(); };
        this._tipHandlers = { over, away };
        document.addEventListener('mouseover', over, true);
        document.addEventListener('mousedown', away, true);
        document.addEventListener('keydown', away, true);
        document.addEventListener('wheel', away, true);
    },

    removeTooltips() {
        const h = this._tipHandlers;
        this._tipHandlers = null;
        this._tipFor = null;
        this.hideTooltip();
        if (!h || typeof document === 'undefined') return;
        document.removeEventListener('mouseover', h.over, true);
        document.removeEventListener('mousedown', h.away, true);
        document.removeEventListener('keydown', h.away, true);
        document.removeEventListener('wheel', h.away, true);
    }
});
